using System;
using System.Text;

namespace ATLASDocGenerator.Services
{
    /// <summary>
    /// Modèles minimaux embarqués dans l'assembly afin que la génération ne
    /// dépende pas de la présence d'une TOC ou d'une target modèle sur le poste.
    /// </summary>
    internal static class EmbeddedDocGeneratorTemplates
    {
        private const string PsTocBase64 =
            "";

        private const string NoticeTocBase64 =
            "";

        private const string DocSavTargetBase64 =
            "";

        internal static string GetPsTocXml()
        {
            return Decode(PsTocBase64);
        }

        internal static string GetDocSavTargetXml()
        {
            return Decode(DocSavTargetBase64);
        }

        internal static string GetNoticeTocXml()
        {
            return Decode(NoticeTocBase64);
        }

        private static string Decode(string base64)
        {
            return Encoding.UTF8
                .GetString(Convert.FromBase64String(base64))
                .TrimStart('\uFEFF');
        }
    }
}
